  const n = src.length;
  const act = aS/n, inh = iS/n, act2 = aS2/n, inh2 = iS2/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.07+t*1.8)*Math.cos(sy*0.06-t*1.4)*0.15;
